import{c as e}from"./card-DD54EzoY.js";var t={listRules(t){return e.get(`/commissions/rules`,{params:t})},getRule(t){return e.get(`/commissions/rules/${t}`)},createRule(t){return e.post(`/commissions/rules`,t)},updateRule(t,n){return e.put(`/commissions/rules/${t}`,n)},deleteRule(t){return e.delete(`/commissions/rules/${t}`)},list(t){return e.get(`/commissions`,{params:t})},getOne(t){return e.get(`/commissions/${t}`)},markPaid(t){return e.patch(`/commissions/${t}/mark-paid`,{})},dispute(t,n){return e.patch(`/commissions/${t}/dispute`,{notes:n})}};export{t};